#include "Image.hpp"
#include <algorithm>
#include <cmath>
#include <stdexcept>
#include <limits>
namespace drowse {
static unsigned char byte(double x){return (unsigned char)std::max(0.,std::min(255.,x+.5));}
Rect intersection(Rect a,Rect b){int x=std::max(a.x,b.x),y=std::max(a.y,b.y);return {x,y,std::max(0,std::min(a.x+a.width,b.x+b.width)-x),std::max(0,std::min(a.y+a.height,b.y+b.height)-y)};}
double distance(Point a,Point b){return std::hypot(a.x-b.x,a.y-b.y);}
Image::Image(int w,int h,unsigned char gray){if(w<1||h<1||w>16384||h>16384||uint64_t(w)*h>100000000)throw std::invalid_argument("Invalid image dimensions");width=w;height=h;stride=(w*3+3)&~3;data.assign((size_t)stride*h,gray);}
void samplePixel(const Image& image,double x,double y,double out[3]){
 if(image.empty()||!std::isfinite(x)||!std::isfinite(y)||x<0||y<0||x>image.width-1||y>image.height-1){out[0]=out[1]=out[2]=0;return;}
 int ix=(int)x,iy=(int)y,jx=std::min(ix+1,image.width-1),jy=std::min(iy+1,image.height-1);double fx=x-ix,fy=y-iy;
 for(int c=0;c<3;++c)out[c]=(1-fy)*((1-fx)*image.row(iy)[ix*3+c]+fx*image.row(iy)[jx*3+c])+fy*((1-fx)*image.row(jy)[ix*3+c]+fx*image.row(jy)[jx*3+c]);
}
Image resizeImage(const Image& image,int width,int height){if(image.empty())throw std::invalid_argument("Cannot resize empty image");if(width==image.width&&height==image.height)return image;Image out(width,height);for(int y=0;y<height;++y)for(int x=0;x<width;++x){double p[3];samplePixel(image,std::max(0.,std::min(image.width-1.,(x+.5)*image.width/width-.5)),std::max(0.,std::min(image.height-1.,(y+.5)*image.height/height-.5)),p);for(int c=0;c<3;++c)out.row(y)[3*x+c]=byte(p[c]);}return out;}
Image cropImage(const Image& image,Rect roi){Rect valid=intersection(roi,{0,0,image.width,image.height});if(valid.area()!=roi.area()||roi.width<=0||roi.height<=0)throw std::invalid_argument("Crop outside image");Image out(roi.width,roi.height);for(int y=0;y<roi.height;++y)std::copy(image.row(roi.y+y)+roi.x*3,image.row(roi.y+y)+(roi.x+roi.width)*3,out.row(y));return out;}
static unsigned char grayAt(const Image& image,int x,int y){const auto p=image.row(y)+x*3;return byte(.114*p[0]+.587*p[1]+.299*p[2]);}
Image grayscale(const Image& image){if(image.empty())return {};Image out(image.width,image.height);for(int y=0;y<image.height;++y)for(int x=0;x<image.width;++x){auto v=grayAt(image,x,y);for(int c=0;c<3;++c)out.row(y)[x*3+c]=v;}return out;}
Image contrastImage(const Image& image){
 Image gray=grayscale(image),out(image.width,image.height);const int nx=8,ny=8;int tw=(image.width+nx-1)/nx,th=(image.height+ny-1)/ny;std::vector<double> lut(nx*ny*256);
 for(int ty=0;ty<ny;++ty)for(int tx=0;tx<nx;++tx){int hist[256]={},count=0;for(int y=ty*th;y<std::min((ty+1)*th,image.height);++y)for(int x=tx*tw;x<std::min((tx+1)*tw,image.width);++x){++hist[gray.row(y)[x*3]];++count;}if(!count)continue;int limit=std::max(1,2*count/256),excess=0;for(int& v:hist){excess+=std::max(0,v-limit);v=std::min(v,limit);}for(int i=0;i<256;++i)hist[i]+=excess/256+(i<excess%256?1:0);int sum=0;for(int i=0;i<256;++i){sum+=hist[i];lut[(ty*nx+tx)*256+i]=sum*255./count;}}
 for(int y=0;y<image.height;++y)for(int x=0;x<image.width;++x){double gx=std::max(0.,std::min(nx-1.,(x+.5)/tw-.5)),gy=std::max(0.,std::min(ny-1.,(y+.5)/th-.5));int x0=(int)gx,y0=(int)gy,x1=std::min(nx-1,x0+1),y1=std::min(ny-1,y0+1),v=gray.row(y)[x*3];double fx=gx-x0,fy=gy-y0;double value=(1-fy)*((1-fx)*lut[(y0*nx+x0)*256+v]+fx*lut[(y0*nx+x1)*256+v])+fy*((1-fx)*lut[(y1*nx+x0)*256+v]+fx*lut[(y1*nx+x1)*256+v]);for(int c=0;c<3;++c)out.row(y)[x*3+c]=byte(value);}
 return out;
}
Image dimImage(const Image& image,double scale,double offset){Image out=image;for(auto& v:out.data)v=byte(v*scale+offset);return out;}
Image rotateImage(const Image& image,double degrees){Image out(image.width,image.height);double a=degrees*3.141592653589793/180,c=std::cos(a),s=std::sin(a),cx=image.width*.5,cy=image.height*.5;for(int y=0;y<out.height;++y)for(int x=0;x<out.width;++x){double p[3];samplePixel(image,cx+c*(x-cx)-s*(y-cy),cy+s*(x-cx)+c*(y-cy),p);for(int k=0;k<3;++k)out.row(y)[x*3+k]=byte(p[k]);}return out;}
Image blurImage(const Image& image,int radius){if(radius<0||radius>1000)throw std::invalid_argument("Invalid blur radius");Image out(image.width,image.height);for(int c=0;c<3;++c){std::vector<uint64_t> integral((size_t)(image.width+1)*(image.height+1));for(int y=1;y<=image.height;++y){uint64_t sum=0;for(int x=1;x<=image.width;++x){sum+=image.row(y-1)[(x-1)*3+c];integral[(size_t)y*(image.width+1)+x]=sum+integral[(size_t)(y-1)*(image.width+1)+x];}}for(int y=0;y<image.height;++y)for(int x=0;x<image.width;++x){int a=std::max(0,x-radius),b=std::min(image.width,x+radius+1),d=std::max(0,y-radius),e=std::min(image.height,y+radius+1);auto get=[&](int xx,int yy){return integral[(size_t)yy*(image.width+1)+xx];};out.row(y)[x*3+c]=byte(double(get(b,e)+get(a,d)-get(a,e)-get(b,d))/((b-a)*(e-d)));}}return out;}
Image fromY16(const uint16_t* input,int width,int height,int strideBytes,double black,double white){if(!input||strideBytes<width*2||black<0||white>65535||white<=black)throw std::invalid_argument("Invalid Y16 buffer or levels");Image out(width,height);for(int y=0;y<height;++y){const uint16_t* row=(const uint16_t*)((const unsigned char*)input+(size_t)y*strideBytes);for(int x=0;x<width;++x){auto value=byte((row[x]-black)*255/(white-black));for(int c=0;c<3;++c)out.row(y)[x*3+c]=value;}}return out;}
void fillRect(Image& image,Rect rect,unsigned char b,unsigned char g,unsigned char r){rect=intersection(rect,{0,0,image.width,image.height});for(int y=rect.y;y<rect.y+rect.height;++y)for(int x=rect.x;x<rect.x+rect.width;++x){auto p=image.row(y)+x*3;p[0]=b;p[1]=g;p[2]=r;}}
void drawRect(Image& image,Rect rect,unsigned char b,unsigned char g,unsigned char r){fillRect(image,{rect.x,rect.y,rect.width,2},b,g,r);fillRect(image,{rect.x,rect.y+rect.height-2,rect.width,2},b,g,r);fillRect(image,{rect.x,rect.y,2,rect.height},b,g,r);fillRect(image,{rect.x+rect.width-2,rect.y,2,rect.height},b,g,r);}
void drawPoint(Image& image,Point p,unsigned char b,unsigned char g,unsigned char r){if(std::isfinite(p.x)&&std::isfinite(p.y)&&p.x>=0&&p.y>=0&&p.x<image.width&&p.y<image.height)fillRect(image,{(int)p.x,(int)p.y,2,2},b,g,r);}
void paste(Image& destination,const Image& source,int x,int y){if(x<0||y<0||x+source.width>destination.width||y+source.height>destination.height)throw std::invalid_argument("Paste outside image");for(int row=0;row<source.height;++row)std::copy(source.row(row),source.row(row)+source.width*3,destination.row(row+y)+x*3);}
Quality quality(const Image& image,Rect roi){Quality q;roi=intersection(roi,{1,1,image.width-2,image.height-2});if(roi.area()<=0)return q;double sum=0,sum2=0,lap=0,lap2=0;int n=roi.area();for(int y=roi.y;y<roi.y+roi.height;++y)for(int x=roi.x;x<roi.x+roi.width;++x){double v=grayAt(image,x,y);sum+=v;sum2+=v*v;q.clipped+=(v<5||v>250)?1:0;q.dark+=v<30?1:0;double l=grayAt(image,x-1,y)+grayAt(image,x+1,y)+grayAt(image,x,y-1)+grayAt(image,x,y+1)-4*v;lap+=l;lap2+=l*l;}q.mean=sum/n;q.sd=std::sqrt(std::max(0.,sum2/n-q.mean*q.mean));q.sharpness=std::max(0.,lap2/n-(lap/n)*(lap/n));q.clipped/=n;q.dark/=n;return q;}
}
